package com.campusnova.exception; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler({SecurityException.class}) public ResponseEntity<Map<String,String>> security(Exception e){return response(HttpStatus.UNAUTHORIZED,e.getMessage());}@ExceptionHandler({IllegalArgumentException.class,NoSuchElementException.class}) public ResponseEntity<Map<String,String>> bad(Exception e){return response(HttpStatus.BAD_REQUEST,e.getMessage());}@ExceptionHandler(Exception.class) public ResponseEntity<Map<String,String>> unknown(Exception e){return response(HttpStatus.INTERNAL_SERVER_ERROR,"Something went wrong. Please try again.");} private ResponseEntity<Map<String,String>> response(HttpStatus s,String msg){return new ResponseEntity<Map<String,String>>(Collections.singletonMap("message",msg),s);} }
